mapper.select:
select rr.resource_id as role_id, rr.name as role_name, rs.resource_id as skill_id, rs.content as skill_name from rtks_role as rr inner join rtks_role_skill_relation as rrsr on rr.resource_id = rrsr.role_id inner join rtks_skill as rs on rrsr.skill_id = rs.resource_id
where rr.resource_id = #{roleId}
order by rr.id, rs.id

select rtks_skill_mission_relation.skill_id as skill_id, count(distinct rtks_skill_mission_relation.mission_template_id) as mission_count, count(distinct cr_task.user_id) as trainee_count from rtks_skill_mission_relation left join cr_task on rtks_skill_mission_relation.mission_template_id = cr_task.mission_template_id where rtks_skill_mission_relation.skill_id in
#{skillId}
group by rtks_skill_mission_relation.skill_id

select distinct user_id
from cr_task where mission_template_id in

    #{missionId}

select rtks_user_role.user_id as user_id, rtks_role.resource_id as role_id, rtks_role.name as role_name from rtks_user_role inner join rtks_role on rtks_user_role.role_id = rtks_role.resource_id
where rtks_role.resource_id = #{roleId}
order by rtks_role.id
